export const packageOptions=[
 {id:'dplyr',description:'filter, select, arrange, mutate, group_by og summarise'},
 {id:'jsonlite',description:'fromJSON og flatten som i OpenSky-filerne'},
 {id:'stringr',description:'str_c, str_detect og str_extract'},
 {id:'tidyr',description:'pivot_wider som i Mikroindikator'},
 {id:'ggplot2',description:'Tegn linjeplot og boksplot, ret plotkode og forstå figurer'}
];
export function enabledExercises(exercises,selected=[]){const active=normalizePackages(selected);return exercises.filter(e=>{const required=(e.packages||[]).length?e.packages:['baseR'];return required.every(p=>active.includes(p));});}
export function normalizePackages(value){const stored=Array.isArray(value)?value:[];const baseR=!stored.includes('__baseR_off__');return [...(baseR?['baseR']:['__baseR_off__']),...packageOptions.map(p=>p.id).filter(p=>stored.includes(p))];}
export const packageExercises=[];
const car='biler <- mtcars';
function add(id,topic,title,prompt,solution,packages,{setup=car,source='Eksamensøvning/Eksamenstræningsopgaver - Svar.R',...extra}={}){
 packageExercises.push({id,topic,title,prompt,solution,packages,setup:packages.map(p=>`library(${p})`).join('\n')+'\n'+setup,source,kind:'code',starter:'# Skriv din løsning her\n',hint:'Brug funktionerne fra de tilvalgte pakker.',explanation:'Samme funktioner og fremgangsmåde som i undervisningsmaterialet; dataene er lokale øvedata.',level:2,check:null,...extra});
}
add('pkg-filter','filter','dplyr · udvælg cylindre','Brug filter() til at returnere biler med 4 eller 8 cylindre.','filter(biler, cyl %in% c(4, 8))',['dplyr'],{hint:'filter(biler, cyl %in% c(4, 8)).'});
add('pkg-select','frames','dplyr · vælg kolonner','Brug select() til at returnere mpg, hp, wt og cyl i denne rækkefølge.','select(biler, mpg, hp, wt, cyl)',['dplyr'],{hint:'Kolonnenavnene skrives efter datasættet, adskilt af komma.'});
add('pkg-arrange','filter','dplyr · faldende sortering','Brug arrange() og desc() til at sortere alle biler efter hp fra højest til lavest.','arrange(biler, desc(hp))',['dplyr']);
add('pkg-mutate','frames','dplyr · omregn hestekræfter','Brug mutate() til at returnere datasættet biler med en ny kolonne kaldet hp_kw. Brug formlen: hp_kw = hp * 0.7457, hvor hp er kolonnen med hestekræfter. Behold også de oprindelige kolonner.','biler |> mutate(hp_kw = hp * 0.7457)',['dplyr'],{hint:'biler |> mutate(nyt_navn = beregning).'});
add('pkg-rename','frames','dplyr · omdøb en kolonne','Brug rename() på datasættet fly. Omdøb kolonnen kode til operator, og behold kolonnen land. Returnér datasættet med det nye kolonnenavn.','rename(fly, operator = kode)',['dplyr'],{setup:'fly <- data.frame(kode = c("SAS", "DLH"), land = c("DK", "DE"))',source:'OpenSky/GetPlanes.R',hint:'rename(data, nyt_navn = gammelt_navn).'});
add('pkg-group','stats','dplyr · spredning pr. område','Brug datasættet kommuner. Gruppér rækkerne efter kolonnen OMRÅDE med group_by(). Beregn standardafvigelsen af value inden for hver gruppe med sd() og summarise(). Returnér én række pr. område med kolonnerne OMRÅDE og spredning. Spring manglende værdier (NA) over med na.rm = TRUE.','kommuner |> group_by(OMRÅDE) |> summarise(spredning = sd(value, na.rm = TRUE))',['dplyr'],{setup:'kommuner <- data.frame(OMRÅDE = c("A", "A", "B", "B"), value = c(28, 30, 31, 35))',source:'Uge 40/Mandag.R'});
add('pkg-json','frames','jsonlite · læs JSON','Opret currentJS ved at læse JSON-teksten current med fromJSON().','currentJS <- fromJSON(current)',['jsonlite'],{setup:'current <- \'{"time":1700000000,"land":"Denmark"}\'',source:'OpenSky/FlyIBox.R',hint:'fromJSON() får selve JSON-teksten som argument.'});
// Assignment checks inspect the created object, just as in the base-R tasks.
packageExercises.find(e=>e.id==='pkg-json').check='identical(currentJS, jsonlite::fromJSON(current))';
add('pkg-json-flat','frames','jsonlite · flad JSON ud','Læs JSON-teksten i objektet tyk2 med fromJSON(..., flatten = TRUE). flatten = TRUE gør de indlejrede felter til almindelige kolonner. Brug derefter as.data.frame(), og returnér det færdige datasæt.','as.data.frame(fromJSON(tyk2, flatten = TRUE))',['jsonlite'],{setup:'tyk2 <- \'[{"position":{"alt":7200},"callsign":"SAS123"},{"position":{"alt":8100},"callsign":"DLH456"}]\'',source:'OpenSky/GetPlanes.R'});
add('pkg-str-c','functions','stringr · byg en hilsen','Brug str_c() til at returnere "Hej Lasse Jensen" ud fra navn og efternavn.','str_c("Hej", " ", navn, " ", efternavn)',['stringr'],{setup:'navn <- "Lasse"\nefternavn <- "Jensen"',source:'OpenSky/gethilsen.R',hint:'str_c() sætter tekststykker sammen. Mellemrum angives som " ".'});
add('pkg-str-detect','vectors','stringr · find tekst','Undersøg hver tekst i vektoren title med str_detect(). Returnér TRUE, hvis teksten indeholder Gas eller gas, og ellers FALSE. Bevar rækkefølgen af teksterne.','str_detect(title, "Gas|gas")',['stringr'],{setup:'title <- c("Gas prices", "Electricity", "Natural gas")',source:'EuroStat/EuroStat.R',hint:'Mønstret "Gas|gas" matcher de to stavemåder.'});
add('pkg-str-extract','vectors','stringr · træk bogstaver ud','Brug str_extract() på vektoren callsign. Hent de store bogstaver før tallene i hvert kaldesign med mønstret "[A-Z]+". Returnér én tekst pr. kaldesign i samme rækkefølge.','str_extract(callsign, "[A-Z]+")',['stringr'],{setup:'callsign <- c("SAS123", "DLH456", "AFR789")',source:'OpenSky/GetPlanes.R'});
add('pkg-combined','filter','dplyr + stringr · filtrér fly','Brug filter() sammen med str_detect() til at vælge rækker fra datasættet currentDF, hvor teksten i kolonnen origin_country indeholder "Iraq". Returnér de valgte rækker med alle kolonner.','currentDF |> filter(str_detect(origin_country, "Iraq"))',['dplyr','stringr'],{setup:'currentDF <- data.frame(callsign = c("A1", "B2", "C3"), origin_country = c("Iraq", "Denmark", "Iraq"))',source:'OpenSky/GetPlanes.R'});
add('pkg-wider','frames','tidyr · fra lang til bred','Brug pivot_wider() på datasættet forventninger. Lav én række pr. TID og én ny kolonne for hver værdi i INDIKATOR. Fyld de nye kolonner med tallene fra value. Brug argumenterne id_cols = TID, names_from = INDIKATOR og values_from = value.','pivot_wider(forventninger, id_cols = TID, names_from = INDIKATOR, values_from = value)',['tidyr'],{setup:'forventninger <- data.frame(TID = c("2024K1", "2024K1", "2024K2", "2024K2"), INDIKATOR = c("A", "B", "A", "B"), value = c(10, 20, 11, 21))',source:'Mikroindikator/Mikroindikator.R'});
add('pkg-plot-line','simulation','ggplot2 · læs et linjeplot','Hvilken funktion i koden tegner linjerne?','geom_line()',['ggplot2'],{setup:'ggplot(kommuner, aes(x = TID, y = value, colour = OMRÅDE, group = OMRÅDE)) + geom_line()',source:'Uge 40/Mandag.R',kind:'choice',options:['geom_line()','aes()','ggplot()','labs()'],answer:0,hint:'geom-funktionen bestemmer, hvordan observationerne tegnes.'});
add('pkg-plot-box','stats','ggplot2 · genkend et boksplot','Hvad tegner denne kode?','Et boksplot af price',['ggplot2'],{setup:'ggplot(dfbilbaseSub, aes(price)) + geom_boxplot()',source:'DALEW36/Onsdag.R',kind:'choice',options:['Et boksplot af price','Et linjediagram','En frekvenstabel','En regressionsmodel'],answer:0,hint:'geom_boxplot() viser fordelingens median, kvartiler og mulige outliers.'});
const development='udvikling <- data.frame(TID = 1:4, value = c(10, 14, 12, 18))';
const regions='udvikling <- data.frame(TID = c(1, 2, 3, 1, 2, 3), value = c(10, 13, 16, 18, 15, 20), OMRÅDE = c("A", "A", "A", "B", "B", "B"))';
const prices='priser <- data.frame(price = c(80, 95, 110, 120, 145, 170, 210, 260), gruppe = c("A", "A", "A", "A", "B", "B", "B", "B"))';
const plotCheck=(geom,columns,colour=false)=>`.plot_matches(.answer, .expected, ${JSON.stringify(geom)}, c(${columns.map(x=>JSON.stringify(x)).join(', ')}), ${colour?'TRUE':'FALSE'})`;
add('gg-line','simulation','ggplot2 · tegn dit første linjeplot','Brug datasættet udvikling. Lav et linjeplot med TID på x-aksen og value på y-aksen. Brug ggplot(), aes() og geom_line(). Lad selve plottet være dit sidste udtryk, så figuren vises.','ggplot(udvikling, aes(x = TID, y = value)) + geom_line()',['ggplot2'],{setup:development,source:'Uge 40/Mandag.R',level:1,hint:'Start med ggplot(udvikling, aes(x = TID, y = value)), og tilføj linjer med + geom_line().',explanation:'aes() knytter kolonner til akserne. geom_line() forbinder værdierne i rækkefølge efter x. Vi tester data og akser, ikke din valgte farve eller stregtykkelse.',check:plotCheck('GeomLine',['x','y','group'])});
add('gg-groups','simulation','ggplot2 · én linje pr. område','Datasættet udvikling indeholder områderne A og B. Tegn TID på x-aksen og value på y-aksen med én linje pr. OMRÅDE. Brug OMRÅDE til både group og colour inde i aes(). Områderne skal have forskellige farver; du må selv vælge farverne.','ggplot(udvikling, aes(x = TID, y = value, group = OMRÅDE, colour = OMRÅDE)) + geom_line()',['ggplot2'],{setup:regions,source:'Uge 40/Mandag.R',hint:'Tilføj group = OMRÅDE og colour = OMRÅDE inde i aes(). group bestemmer, hvilke punkter der forbindes.',explanation:'Hvert område får sin egen linje. Farven varierer efter området, fordi colour står inde i aes().',check:plotCheck('GeomLine',['x','y','group'],true)});
add('gg-box','stats','ggplot2 · tegn et boksplot','Brug datasættet priser. Tegn ét boksplot af hele kolonnen price med price på y-aksen. Brug ggplot(), aes() og geom_boxplot(). Du skal ikke opdele efter gruppe i denne opgave.','ggplot(priser, aes(y = price)) + geom_boxplot()',['ggplot2'],{setup:prices,source:'DALEW36/Onsdag.R',level:1,hint:'Brug aes(y = price), og tilføj + geom_boxplot(). Du behøver ikke angive en x-variabel for ét boksplot.',explanation:'Boksplottet viser median, kvartiler og spredning for alle priserne samlet. Farver og tema vurderes ikke.',check:plotCheck('GeomBoxplot',['x','ymin','lower','middle','upper','ymax','group'])});
add('gg-box-groups','stats','ggplot2 · sammenlign to boksplot','Brug datasættet priser. Tegn ét boksplot for hver gruppe: gruppe på x-aksen og price på y-aksen. Begge grupper A og B skal med. Du må gerne vælge farver, men det er ikke et krav.','ggplot(priser, aes(x = gruppe, y = price)) + geom_boxplot()',['ggplot2'],{setup:prices,source:'DALEW36/Onsdag.R',hint:'Den tekstbaserede kolonne gruppe skal stå som x inde i aes(). Hver gruppe får automatisk sit eget boksplot.',explanation:'De to boksplot gør det muligt at sammenligne prisernes fordeling i gruppe A og B.',check:plotCheck('GeomBoxplot',['x','ymin','lower','middle','upper','ymax','group'])});
add('gg-debug-axes','simulation','ggplot2 · ret de ombyttede akser','Koden har byttet om på akserne. Ret plottet, så TID står på x-aksen og value på y-aksen. Behold et linjeplot med alle rækker fra udvikling.','ggplot(udvikling, aes(x = TID, y = value)) + geom_line()',['ggplot2'],{setup:development,source:'Uge 40/Mandag.R',kind:'debug',starter:'ggplot(udvikling, aes(x = value, y = TID)) + geom_line()',hint:'x skal være TID, og y skal være value inde i aes().',explanation:'Tiden står på x-aksen, og de målte værdier står på y-aksen.',check:plotCheck('GeomLine',['x','y','group'])});
